import requests
import json
import pandas as pd
import seaborn as sns
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    import matplotlib.pyplot as plt

    if not url or not isinstance(url, str):
        raise Exception("Invalid URL provided.")

    try:
        response = requests.get(url, params=parameters, headers=HEADERS)
        response.raise_for_status()
        data = response.json()
    except Exception as e:
        raise Exception(f"URL cannot be accessed or invalid data: {e}")

    if not data:
        raise Exception("Empty data received.")

    try:
        df = pd.DataFrame(data)
        if df.empty:
            raise Exception("Empty data.")

        numeric_df = df.select_dtypes(include=['number'])
        if numeric_df.empty:
            raise Exception("No numerical data for correlation.")

        corr = numeric_df.corr()
        ax = sns.heatmap(corr, annot=True, cmap='coolwarm')
    except Exception as e:
        raise Exception(f"Invalid data or processing error: {e}")

    return df, ax

